354		}
355		r := statusOf(t, q, "m")
356		if r.Attempts != 1 {
357			t.Fatalf("equal-time re-advance at retry boundary must not double-process: %d", r.Attempts)
358		}
359		if _, err := q.Advance(999); !errors.Is(err, ErrInvalidArg) {
360			t.Fatalf("backwards advance must fail with ErrInvalidArg, got %v", err)
361		}
362		if q.Now() != 1000 {
363			t.Fatalf("failed advance changed processing time: %d", q.Now())
364		}
365	}
