383	func TestAllSixStatesDistinguishable(t *testing.T) {
384		q, _ := openTempQueue(t)
385		defer q.Close()
386		q.RegisterSource("a")
387		q.UpsertHeader(Header{Chain: "a", Height: 100, Trusted: true})
388	
389		q.Submit(env("s-ok", "a", "b", 1, 10, 0))
390		q.Submit(env("s-replay", "a", "b", 1, 10, 0))
391		q.Submit(env("s-expired", "a", "b", 2, 10, 1000))
392		q.Submit(env("s-alien", "mars", "b", 0, 10, 0))
393		q.Submit(env("s-wait", "a", "b", 7, 1000, 0)) // proof height above header
394		q.Submit(env("s-pending", "a", "b", 8, 10, 0))
395	
396		q.Advance(1000)
397		// s-pending was submitted before the advance, so it processes too; make a
398		// genuinely fresh submission afterwards for the pending state.
399		q.Submit(env("s-fresh", "a", "b", 9, 10, 0))
400	
401		want := map[string]string{
402			"s-ok":      StatusSuccess,
403			"s-replay":  StatusReplay,
404			"s-expired": StatusExpired,
405			"s-alien":   StatusUnknownSrc,
406			"s-wait":    StatusWaiting,
407			"s-fresh":   StatusPending,
408		}
409		for id, st := range want {
410			r, ok := q.Query(id)
411			if !ok {
412				t.Fatalf("missing %s", id)
413			}
414			if r.Status != st {
415				t.Fatalf("%s: want %s got %s (%s)", id, st, r.Status, r.Reason)
416			}
417			if r.Reason == "" {
418				t.Fatalf("%s: reason must be specific", id)
419			}
420			switch st {
421			case StatusPending, StatusSuccess, StatusReplay, StatusExpired, StatusUnknownSrc:
422				if r.NextRetry != 0 {
423					t.Fatalf("%s: must have no retry time, got %d", id, r.NextRetry)
424				}
425			case StatusWaiting:
426				if r.NextRetry != 2000 {
427					t.Fatalf("%s: retry at 2000, got %d", id, r.NextRetry)
428				}
429			}
430		}
431	}
